class Solution:
    def DistinictSum(self, nums):
        total_sum = sum(nums)
        n = len(nums)

        # dp[j] will be True if sum j is possible
        dp = [False] * (total_sum + 1)
        dp[0] = True

        for num in nums:
            for j in range(total_sum, num - 1, -1):
                if dp[j - num]:
                    dp[j] = True

        # Collect all sums that are possible
        result = [i for i in range(total_sum + 1) if dp[i]]
        return result

