def findTwoElement(arr, n):
    repeating = -1
    missing = -1

    # Find the repeating element
    for i in range(n):
        idx = abs(arr[i]) - 1
        if arr[idx] < 0:
            repeating = abs(arr[i])
        else:
            arr[idx] = -arr[idx]

    # Find the missing element
    for i in range(n):
        if arr[i] > 0:
            missing = i + 1
            break

    return [repeating, missing]

