def computeBeforeMatrix(N, M, after):
    before = [[0] * M for _ in range(N)]

    for i in range(N):
        for j in range(M):
            # Start with the current after value
            val = after[i][j]

            # Subtract the top prefix sum if it exists
            if i > 0:
                val -= after[i - 1][j]

            # Subtract the left prefix sum if it exists
            if j > 0:
                val -= after[i][j - 1]

            # Add back the top-left overlapping region if both exist
            if i > 0 and j > 0:
                val += after[i - 1][j - 1]

            before[i][j] = val

    return before

