def asteroidCollision(N, asteroids):
    stack = []
    for ast in asteroids:
        # Process collision only if current ast is moving left and stack top is moving right
        while stack and ast < 0 and stack[-1] > 0:
            if stack[-1] < -ast:
                stack.pop()
                continue
            elif stack[-1] == -ast:
                stack.pop()
            break
        else:
            stack.append(ast)
    return stack

