def trump_detector(s: str) -> float:
    s = s.lower()
    vowels = set("aeiou")

    extra_vowels = 0
    base_vowels = 0

    i = 0
    n = len(s)
    while i < n:
        if s[i] in vowels:
            # Found the start of a vowel group
            v = s[i]
            count = 0
            while i < n and s[i] == v:
                count += 1
                i += 1

            base_vowels += 1
            if count > 1:
                extra_vowels += (count - 1)
        else:
            i += 1

    if base_vowels == 0:
        return 0.0

    return round(extra_vowels / base_vowels, 2)

