class Solution:
    def primeProduct(self, L: int, R: int) -> int:
        MOD = 10**9 + 7

        # Limit for sieve is sqrt(R)
        limit = int(R**0.5)

        # Step 1: Find all primes up to sqrt(R) using simple sieve
        is_prime = [True] * (limit + 1)
        if limit >= 0:
            is_prime[0] = False
        if limit >= 1:
            is_prime[1] = False

        p = 2
        while p * p <= limit:
            if is_prime[p]:
                for i in range(p * p, limit + 1, p):
                    is_prime[i] = False
            p += 1

        primes = [i for i in range(limit + 1) if is_prime[i]]

        # Step 2: Segmented sieve for range [L, R]
        # Handle case where L = 1
        range_size = R - L + 1
        segment = [True] * range_size

        for p in primes:
            # Find the minimum number in [L, R] that is a multiple of p
            base = (L // p) * p
            if base < L:
                base += p

            # If base is prime itself (i.e., base == p), we start marking from p * 2
            start = max(base, p * p)

            for j in range(start, R + 1, p):
                segment[j - L] = False

        # Handle L = 1 explicitly
        if L == 1:
            segment[0] = False

        # Step 3: Calculate product of primes in the range [L, R]
        product = 1
        for i in range(range_size):
            if segment[i]:
                prime_num = L + i
                product = (product * prime_num) % MOD

        return product

